package com.hardrock.eventexporter;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 private TextView status;private String pending="";
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(28,35,28,20);TextView heading=new TextView(this);heading.setText("Hard Rock Auto Event Exporter");heading.setTextSize(23);layout.addView(heading);TextView help=new TextView(this);help.setText("Open the Hard Rock Reserved Events screen, then return here and tap Start. Switch back to Hard Rock during the 5-second countdown. Text-only scanning; verify all exports.");help.setPadding(0,18,0,18);layout.addView(help);status=new TextView(this);status.setText("Ready");layout.addView(status);add(layout,"Enable Accessibility",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));add(layout,"Start Auto Scan (5 seconds)",()->{if(EventAccessibilityService.instance==null){status.setText("Enable Accessibility first");return;}EventAccessibilityService.instance.startScan();status.setText("Switch to Hard Rock Reserved Events now");});add(layout,"Stop Scan",()->{if(EventAccessibilityService.instance!=null)EventAccessibilityService.instance.stopScan();status.setText("Stopped");});add(layout,"View Results",()->{StringBuilder s=new StringBuilder(EventStore.items.size()+" events\n");for(EventStore.Item i:EventStore.items.values())s.append(i.date).append(" | ").append(i.title).append(" | ").append(i.time).append('\n');status.setText(s.toString());});add(layout,"Export CSV",()->export("text/csv","hardrock_events.csv",EventStore.csv()));add(layout,"Export Calendar ICS",()->export("text/calendar","hardrock_events.ics",EventStore.ics()));ScrollView scroll=new ScrollView(this);scroll.addView(layout);setContentView(scroll);}
 private void add(LinearLayout l,String label,Runnable r){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->r.run());l.addView(b);}
 private void export(String mime,String name,String content){pending=content;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,10);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==10&&result==RESULT_OK&&data!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pending.getBytes(StandardCharsets.UTF_8));status.setText("Saved");}catch(Exception e){status.setText("Export error: "+e.getMessage());}}}
}
